-- TESTING only; existing account, isolated fixtures, complete rollback.
begin;
create function pg_temp.stock_assert(ok boolean,label text) returns void language plpgsql as $$begin
 if ok is distinct from true then raise exception 'Sales/stock sources assertion: %',label;end if;end$$;
create function pg_temp.stock_error(statement text,expected text) returns void language plpgsql as $$begin
 begin execute statement;exception when others then if sqlerrm=expected then return;end if;raise exception 'expected %, got %',expected,sqlerrm;end;
 raise exception 'expected % but command succeeded',expected;end$$;
do $test$
declare f uuid;actor uuid;technician uuid;p uuid;ext uuid;hybrid uuid;guardp uuid;material uuid;semi uuid;ln uuid;wc uuid;s uuid;line uuid;job uuid;hybrid_request uuid;hybrid_job uuid;move uuid;retry uuid;info jsonb;guide jsonb;old_orders jsonb;due timestamptz;planned jsonb;estimate timestamptz;
begin
 select m.factory_id,m.user_id into f,actor from public.memberships m join public.factories fac on fac.id=m.factory_id where fac.is_demo and m.status='approved' and m.is_owner limit 1;
 if f is null then raise exception 'existing TESTING account required';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 update public.production_shifts set archived=true where factory_id=f and not archived;
 update public.factories set working_days_mask=127,workday_start='00:00',workday_end='23:59' where id=f;
 insert into public.products(factory_id,name,code,unit) values(f,'Source QA manufactured','SOURCE-'||substr(gen_random_uuid()::text,1,8),'meter') returning id into p;
 insert into public.products(factory_id,name,code,unit) values(f,'Source QA external','SOURCE-'||substr(gen_random_uuid()::text,1,8),'piece') returning id into ext;
 insert into public.products(factory_id,name,code,unit) values(f,'Source QA hybrid','SOURCE-'||substr(gen_random_uuid()::text,1,8),'meter') returning id into hybrid;
 perform pg_temp.stock_assert((select supply_source='MANUFACTURED' from public.products where id=p),'existing/default manufacturing semantics');
 perform public.configure_warehouse_product(f,p,'MANUFACTURED','MAKE_TO_ORDER','meter');
 perform public.configure_warehouse_product(f,ext,'EXTERNAL','MAKE_TO_STOCK','piece',20,50);
 perform public.configure_warehouse_product(f,hybrid,'BOTH','MAKE_TO_STOCK','meter',20,50);
 perform pg_temp.stock_assert(not exists(select 1 from public.production_orders where product_id in(ext,hybrid)),'external/hybrid low stock never auto manufactures');
 retry:=gen_random_uuid();move:=public.receive_warehouse_stock(f,p,'finished','meter',150,'opening_balance','QA opening','Initial counted inventory',retry);
 perform pg_temp.stock_assert(move=public.receive_warehouse_stock(f,p,'finished','meter',150,'opening_balance','QA opening','Initial counted inventory',retry),'receipt retry same identity');
 perform pg_temp.stock_assert((select on_hand=150 and reserved=0 from public.finished_goods_balances where product_id=p),'opening stock exactly once');
 perform pg_temp.stock_assert((select kind='opening_balance' and stock_delta=150 and unit='meter' and created_by=actor and created_at is not null and external_reference='QA opening' from public.finished_goods_movements where id=move),'opening audit fields');
 perform pg_temp.stock_assert(exists(select 1 from public.audit_logs where entity='finished_goods_movements' and entity_id=move),'opening audit log');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,p,'finished','meter','opening_balance'),'stock_opening_exists');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,p,'finished','kg','external_receipt'),'fulfillment_stock_identity');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,-1,%L)',f,p,'finished','meter','external_receipt'),'fulfillment_invalid');
 perform pg_temp.stock_error(format('select public.configure_product_stock(%L,%L,%L,%L)',f,p,'MAKE_TO_ORDER','piece'),'fulfillment_stock_identity');
 perform pg_temp.stock_assert(not exists(select 1 from public.production_orders where product_id=p),'opening does not create production');
 insert into public.products(factory_id,name,code,unit) values(f,'Source QA draft unit','SOURCE-'||substr(gen_random_uuid()::text,1,8),'piece') returning id into guardp;
 s:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',guardp,'quantity',1,'unit','piece'))));
 perform pg_temp.stock_error(format('select public.configure_product_stock(%L,%L,%L,%L)',f,guardp,'MAKE_TO_ORDER','meter'),'fulfillment_stock_identity');
 perform public.configure_product_stock(f,guardp,'MAKE_TO_ORDER','piece');
 perform pg_temp.stock_error(format('insert into public.sales_order_lines(factory_id,order_id,product_id,quantity,unit) values(%L,%L,%L,1,%L)',f,s,p,'piece'),'fulfillment_stock_identity');
 -- A/D: no date and opening inventory fulfill Sales with no fake urgency.
 s:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',100,'unit','meter'))));perform public.approve_sales_order(f,s);
 info:=private.sales_order_detail(f,s);
 perform pg_temp.stock_assert(info->>'requested_delivery' is null and info->>'target_ready' is null and info->>'requested_feasible' is null and info->>'risk'='none','NULL target stays absent');
 perform pg_temp.stock_assert(info->>'fulfillment_status'='ready' and (info->>'dispatch_allowed')::boolean and (info->'lines'->0->>'production_required')::numeric=0,'opening stock satisfies Sales');
 perform pg_temp.stock_assert((select on_hand=150 and reserved=100 from public.finished_goods_balances where product_id=p),'reserve preserves physical stock');
 perform pg_temp.stock_assert(exists(select 1 from jsonb_array_elements(public.warehouse_movements(f,p,'finished')->'rows') x where x->>'kind'='reservation' and (x->>'quantity')::numeric=0 and (x->>'reserved_delta')::numeric=100),'movement reader separates physical stock from reservations');
 perform public.dispatch_sales_order(f,s);perform pg_temp.stock_assert((select on_hand=50 and reserved=0 from public.finished_goods_balances where product_id=p),'existing dispatch preserved');
 -- E/F: externally sourced stock and shortage, receipt fills the reservation, no PR.
 move:=public.receive_warehouse_stock(f,ext,'finished','piece',10,'external_receipt','QA import','Counted receipt');
 perform pg_temp.stock_assert((select created_by=actor and unit='piece' and stock_delta=10 and kind='external_receipt' from public.finished_goods_movements where id=move),'external traceability');
 s:=public.create_sales_order(f,jsonb_build_object('requested_delivery',now()+interval '10 days','lines',jsonb_build_array(jsonb_build_object('product_id',ext,'quantity',15,'unit','piece'))));perform public.approve_sales_order(f,s);
 info:=private.sales_order_detail(f,s);perform pg_temp.stock_assert((info->'lines'->0->>'external_shortage')::numeric=5 and (info->'lines'->0->>'production_required')::numeric=0 and info->>'estimated_ready' is null,'external shortage visible, no fabricated ready date');
 perform public.receive_warehouse_stock(f,ext,'finished','piece',5,'external_receipt');
 info:=private.sales_order_detail(f,s);perform pg_temp.stock_assert((info->'lines'->0->>'reserved_quantity')::numeric=15 and (info->>'dispatch_allowed')::boolean,'receipt automatically reserves uncovered Sales');
 perform pg_temp.stock_assert(not exists(select 1 from public.production_orders where product_id=ext),'external demand/receipts never creates Sales or stock production');
 perform pg_temp.stock_error(format('insert into public.production_orders(factory_id,product_id,target_quantity,unit) values(%L,%L,1,%L)',f,ext,'piece'),'fulfillment_source_decision');
 perform public.dispatch_sales_order(f,s);
 -- BOTH requires a decision, but received stock still fulfills normally.
 s:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',hybrid,'quantity',12,'unit','meter'))));perform public.approve_sales_order(f,s);
 info:=private.sales_order_detail(f,s);perform pg_temp.stock_assert((info->'lines'->0->>'source_decision_quantity')::numeric=12 and not exists(select 1 from public.production_orders where product_id=hybrid),'hybrid shortage human decision');
 perform public.receive_warehouse_stock(f,hybrid,'finished','meter',12,'external_receipt');
 perform pg_temp.stock_assert((private.sales_order_detail(f,s)->>'dispatch_allowed')::boolean,'hybrid stock can fulfill Sales');
 -- G: materials have their own unit and existing ledger, not finished-goods balances.
 material:=public.create_warehouse_material(f,jsonb_build_object('name','Source QA resin','code','SOURCE-'||substr(gen_random_uuid()::text,1,8),'unit','kg'),gen_random_uuid());
 insert into public.materials(factory_id,name,code,unit,inventory_kind) values(f,'Legacy Source QA blank','SOURCE-'||substr(gen_random_uuid()::text,1,8),'piece','SEMI_FINISHED') returning id into semi;
 move:=public.receive_warehouse_stock(f,material,'material','kg',2500,'opening_balance','QA resin opening');
 perform public.receive_warehouse_stock(f,material,'material','kg',300,'external_receipt','QA resin receipt');
 perform public.receive_warehouse_stock(f,semi,'material','piece',25,'external_receipt');
 perform pg_temp.stock_assert((select sum(quantity)=2800 from public.inventory_transactions where material_id=material),'raw on hand is material ledger sum');
 perform pg_temp.stock_assert((select unit='kg' and created_by=actor and kind='opening_balance' from public.inventory_transactions where id=move),'material unit/actor retained');
 perform pg_temp.stock_assert(exists(select 1 from jsonb_array_elements(public.warehouse_page(f)->'materials') x where x->>'id'=material::text and (x->>'on_hand')::numeric=2800),'materials visible in Warehouse');
 perform pg_temp.stock_assert((public.warehouse_movements(f,material,'material')->>'total')::integer=2,'movement reader reuses material ledger');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,material,'material','piece','external_receipt'),'fulfillment_stock_identity');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,material,'material','kg','opening_balance'),'stock_opening_exists');
 perform pg_temp.stock_error(format('update public.materials set unit=%L where id=%L','meter',material),'fulfillment_stock_identity');
 insert into public.materials(factory_id,name,code,unit) values(f,'Legacy unit-count material','SOURCE-'||substr(gen_random_uuid()::text,1,8),'unit') returning id into material;
 move:=public.receive_warehouse_stock(f,material,'material','unit',5,'external_receipt');
 perform pg_temp.stock_assert((select unit='unit' and quantity=5 from public.inventory_transactions where id=move),'legacy configured unit retained exactly');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,material,'material','piece','external_receipt'),'fulfillment_stock_identity');
 -- B: no date creates unscheduled manufactured demand; readiness follows only saved/actual truth.
 insert into public.production_lines(factory_id,name,code) values(f,'Source QA line','SOURCE-'||substr(gen_random_uuid()::text,1,8)) returning id into ln;
 insert into public.work_centers(factory_id,name,code,line_id,category_id) select f,'Source QA machine','SOURCE-'||substr(gen_random_uuid()::text,1,8),ln,category_id from public.work_centers where factory_id=f and category_id is not null limit 1 returning id into wc;
 insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit,setup_minutes) values(f,wc,p,100,'meter',30);
 -- A deliberate Internal Production decision can satisfy a hybrid shortage after Good receipt.
 insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit) values(f,wc,hybrid,100,'meter');
 s:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',hybrid,'quantity',5,'unit','meter'))));perform public.approve_sales_order(f,s);
 hybrid_request:=public.create_production_request(f,'Hybrid source decision','normal',null,'QA deliberate make decision',jsonb_build_array(jsonb_build_object('product_id',hybrid,'quantity',5,'unit','meter')));
 select id into hybrid_job from public.production_orders where request_id=hybrid_request;
 update public.production_orders set line_id=ln,start_time=now()-interval '1 hour',expected_finish=now()+interval '1 hour' where id=hybrid_job;
 perform public.start_product_item(f,hybrid_job);
 select id into technician from public.memberships where factory_id=f and user_id=actor;
 perform public.record_production(f,'line',ln,hybrid_job,technician,5,0);perform public.finish_product_item(f,hybrid_job);
 perform pg_temp.stock_assert((private.sales_order_detail(f,s)->>'dispatch_allowed')::boolean,'deliberate hybrid Good output reserves approved Sales shortage');
 s:=public.create_sales_order(f,jsonb_build_object('lines',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',150,'unit','meter'))));perform public.approve_sales_order(f,s);
 select id into line from public.sales_order_lines where order_id=s;
 select o.id into job from public.production_orders o join public.production_requests r on r.id=o.request_id where r.sales_order_line_id=line;
 perform pg_temp.stock_assert((select target_quantity=100 and start_time is null from public.production_orders where id=job),'manufactured shortage creates only required 100');
 perform pg_temp.stock_assert((select r.required_by is null and r.priority='normal' from public.production_requests r join public.production_orders o on o.request_id=r.id where o.id=job),'missing date no fabricated deadline/urgency');
 perform pg_temp.stock_assert(private.sales_order_detail(f,s)->>'estimated_ready' is null and public.sales_planning_slot(f,job) is null and public.sales_planning_guidance(f,job)->>'state'='no_target','no fake backward slot or persisted readiness');
 due:=now()+interval '10 days';perform public.change_sales_order(f,s,jsonb_build_object('requested_delivery',due),'QA customer now provides target');
 select jsonb_agg(to_jsonb(o) order by o.id) into old_orders from public.production_orders o;
 guide:=public.sales_planning_guidance(f,job);
 perform pg_temp.stock_assert(guide->>'state'='achievable' and (guide->'suggestion'->>'minutes')::numeric=90,'authoritative setup plus quantity/rate duration');
 perform pg_temp.stock_assert(old_orders=(select jsonb_agg(to_jsonb(o) order by o.id) from public.production_orders o),'guidance never writes schedule');
 perform public.change_sales_order(f,s,jsonb_build_object('requested_delivery',now()+interval '3 hours'),'QA tight customer target');
 perform pg_temp.stock_assert(public.sales_planning_guidance(f,job)->>'state'='tight','target achievable without preferred buffer');
 perform public.change_sales_order(f,s,jsonb_build_object('requested_delivery',now()+interval '1 minute'),'QA impossible customer target');
 perform pg_temp.stock_assert(public.sales_planning_guidance(f,job)->>'state'='unachievable','known capacity cannot meet customer target');
 delete from public.work_center_capabilities where work_center_id=wc;
 perform pg_temp.stock_assert(public.sales_planning_guidance(f,job)->>'state'='insufficient','missing capability data explicitly unknown');
 insert into public.work_center_capabilities(factory_id,work_center_id,product_id,rate,rate_unit,setup_minutes) values(f,wc,p,100,'meter',30);
 perform public.change_sales_order(f,s,jsonb_build_object('requested_delivery',due),'QA restore target');
 update public.production_orders set line_id=ln,start_time=now()+interval '1 day',expected_finish=now()+interval '1 day 90 minutes' where id=job;
 estimate:=(private.sales_order_detail(f,s)->>'estimated_ready')::timestamptz;
 perform pg_temp.stock_assert(estimate=(select expected_finish from public.production_orders where id=job),'saved planned finish reaches Sales');
 perform set_config('app.plan_reason','customer_request',true);
 update public.production_orders set start_time=start_time+interval '1 day',expected_finish=expected_finish+interval '1 day' where id=job;
 perform pg_temp.stock_assert((private.sales_order_detail(f,s)->>'estimated_ready')::timestamptz=estimate+interval '1 day','replanning immediately changes derived estimate');
 update public.production_orders set start_time=now()-interval '1 hour',expected_finish=now()+interval '30 minutes' where id=job;
 select jsonb_build_array(start_time,expected_finish) into planned from public.production_orders where id=job;
 perform public.start_product_item(f,job);
 perform pg_temp.stock_assert((private.sales_order_detail(f,s)->>'estimated_ready')::timestamptz>(select expected_finish from public.production_orders where id=job),'late actual start affects estimate without overwriting plan');
 perform pg_temp.stock_assert(planned=(select jsonb_build_array(start_time,expected_finish) from public.production_orders where id=job),'actual start preserves planning');
 perform pg_temp.stock_error(format('select public.change_sales_order(%L,%L,%L::jsonb,%L)',f,s,jsonb_build_object('promised_delivery',due),'QA promise injection'),'sales_promise_read_only');
 perform pg_temp.stock_error(format('update public.sales_orders set promised_delivery=now() where id=%L',s),'sales_promise_read_only');
 perform pg_temp.stock_error(format('select public.create_sales_order(%L,%L::jsonb)',f,jsonb_build_object('promised_delivery',null,'lines',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'unit','meter')))),'sales_promise_read_only');
 perform pg_temp.stock_assert(not has_table_privilege('authenticated','public.inventory_transactions','insert') and not has_table_privilege('authenticated','public.inventory_transactions','update'),'material ledger direct writes denied');
 perform pg_temp.stock_assert(not has_function_privilege('anon','public.receive_warehouse_stock(uuid,uuid,text,text,numeric,text,text,text,uuid)','execute'),'anonymous receipt denied');
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,p,'finished','meter','external_receipt'),'permission_denied');
 perform pg_temp.stock_error(format('select public.create_warehouse_material(%L,%L::jsonb,%L)',f,'{}',gen_random_uuid()),'permission_denied');
 perform pg_temp.stock_error(format('select public.warehouse_movements(%L,%L,%L)',f,material,'material'),'permission_denied');
 perform set_config('request.jwt.claim.sub',actor::text,true);
 delete from public.user_permissions where factory_id=f and user_id=actor and module='warehouse' and action='edit';
 perform pg_temp.stock_assert(public.warehouse_page(f) is not null,'view survives removal of mutation grant');
 perform pg_temp.stock_error(format('select public.receive_warehouse_stock(%L,%L,%L,%L,1,%L)',f,p,'finished','meter','external_receipt'),'permission_denied');
 perform pg_temp.stock_error(format('select public.configure_warehouse_product(%L,%L,%L,%L,%L)',f,p,'MANUFACTURED','MAKE_TO_ORDER','meter'),'permission_denied');
 set constraints all immediate;
end$test$;
rollback;
select 'Sales dates, stock sources, raw/semi materials, scheduling/actual readiness, traceability, retries, unit guards and permissions passed' result;
